mapper.select:
SELECT s.song_id FROM songs_tbl s JOIN song_keyword_tbl sk ON s.song_id = sk.song_id JOIN (
SELECT #{ks.keywordId} AS keyword_id, #{ks.totalScore} AS kw_score FROM DUAL
) kw ON sk.keyword_id = kw.keyword_id GROUP BY s.song_id ORDER BY SUM(kw.kw_score) DESC FETCH FIRST #{amount} ROWS ONLY
